import org.junit.jupiter.params.provider.ValueSource;

/** Collaborator-boundary control; an unsaved replacement is not claimed to be a supported production actor. */
class LmdbDiscoveryWitnessReplacementTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:discovery-witness:subject");
	private static final IRI EXCLUDED = VF.createIRI("urn:discovery-witness:excluded");
	private static final IRI Q = VF.createIRI("urn:discovery-witness:marked");
	private static final IRI O = VF.createIRI("urn:discovery-witness:object");

	@ParameterizedTest(name = "replace witness={0}")
	@ValueSource(booleans = { false, true })
	void aDifferentProfileCannotBorrowAnEarlierQualifiedSnapshot(boolean replace,
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("excluded-store");
		Path defaultDirectory = evidence.resolve("default-profile-store");
		LmdbStoreConfig excludedConfig = config().setPredicateGuaranteeExcludedPredicates(EXCLUDED.stringValue());
		LmdbStoreConfig defaultConfig = config();
		seed(directory, excludedConfig);
		seed(defaultDirectory, defaultConfig);

		StoreProperties properties = load(directory);
		StoreProperties otherProperties = load(defaultDirectory);
		String oldEncoded = properties.getRdfTermDomainQualification();
		RdfTermDomainQualification.Witness oldWitness = RdfTermDomainQualification.decode(oldEncoded);
		RdfTermDomainQualification.Witness otherWitness = RdfTermDomainQualification
				.decode(otherProperties.getRdfTermDomainQualification());
		assertNotNull(oldWitness, "the excluded-profile store must publish a real qualification");
		assertNotNull(otherWitness, "the default-profile store must publish a real qualification");
		assertNotEquals(oldWitness.version(), otherWitness.version(), "the real profiles must differ");
		assertTrue(LmdbCompatibilityFixtures.nativeTripleEntryCount(directory,
				TripleStore.PREDICATE_OBJECT_DOMAIN_DEGRADATIONS_DB) > 0,
				"a real marked predicate must force ordinary discovery");
		assertNull(PreparedBulkStore.read(directory, properties, excludedConfig));
		assertTrue(properties.rdfTermDomainQualifiedAtOpen,
				"the first real capture must have qualified the original profile");
		LegacyStoreDiscovery.discover(directory.toFile(), properties);
		assertEquals(oldWitness.valuesTransaction(), properties.verifiedValueTransactionId);
		assertEquals(oldWitness.triplesTransaction(), properties.verifiedTripleTransactionId);
		assertEquals(oldWitness.valuesTransaction(), LmdbCompatibilityFixtures.nativeTransactionId(directory));
		Files.copy(directory.resolve("store.properties"), evidence.resolve("before-in-memory-replacement.properties"));

		if (replace) {
			properties.setRdfTermDomainsVersion(otherWitness.version());
			properties.setRdfTermDomainQualification(new RdfTermDomainQualification.Witness(otherWitness.version(),
					oldWitness.valuesTransaction(), oldWitness.triplesTransaction(), oldWitness.generation()).encode());
			assertNotEquals(oldEncoded, properties.getRdfTermDomainQualification());
		}
		RdfTermDomainQualification.beginPairedWriter(directory, properties, replace ? defaultConfig : excludedConfig);
		if (replace) {
			assertFalse(properties.rdfTermDomainQualifiedAtOpen,
					"a different profile must not inherit qualification of an earlier witness");
			assertNull(properties.getRdfTermDomainQualification(), "the unqualified replacement must be withdrawn");
		} else {
			assertTrue(properties.rdfTermDomainQualifiedAtOpen, "the unchanged actual witness remains qualified");
			assertEquals(oldEncoded, properties.getRdfTermDomainQualification());
		}
		assertEquals(oldWitness.valuesTransaction(), LmdbCompatibilityFixtures.nativeTransactionId(directory),
				"the collaborator control itself must not change the native dictionary generation");

		LmdbStore reopened = new LmdbStore(directory.toFile(), excludedConfig);
		SailRepository repository = new SailRepository(reopened);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(reopened, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				assertTrue(connection.hasStatement(S, EXCLUDED, O, false), "the excluded row must survive");
				assertTrue(connection.hasStatement(S, Q, O, false), "the marked predicate's live row must survive");
				assertFalse(connection.hasStatement(S, Q, VF.createLiteral("deleted"), false));
			}
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false)
				.setForceSync(true)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setPredicateGuaranteeIndexEnabled(true)
				.setPredicateGuaranteeIndexAutoRebuild(true);
	}

	private static StoreProperties load(Path directory) throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertTrue(properties.load());
		return properties;
	}

	private static void seed(Path directory, LmdbStoreConfig config) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(S, EXCLUDED, O);
				connection.add(S, Q, O);
				connection.add(S, Q, VF.createLiteral("deleted"));
				connection.commit();
				connection.begin();
				connection.remove(S, Q, VF.createLiteral("deleted"));
				connection.commit();
			}
		} finally {
			repository.shutDown();
		}
	}
}
